"""Validated single-ticket inputs and the three fields generated by the API."""

import re
from typing import Literal

from pydantic import BaseModel, ConfigDict, Field, ValidationInfo, field_validator, model_validator


Category = Literal["Bug Report", "Feature Request", "Billing Issue", "General Inquiry", "Customer Feedback"]
Sentiment = Literal["Positive", "Neutral", "Negative"]
Priority = Literal["Low", "Medium", "High", "Urgent"]


class TicketInput(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True, hide_input_in_errors=True)

    ticket_id: str
    message: str

    @field_validator("ticket_id")
    @classmethod
    def nonblank_id(cls, value):
        value = value.strip()
        if not value:
            raise ValueError("A nonblank ticket ID is required.")
        return value


class GenerationContext(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True, hide_input_in_errors=True)

    message: str = Field(min_length=1, max_length=12000)
    category: Category
    sentiment: Sentiment


def _normalized(value: str) -> str:
    return " ".join(value.casefold().split())


_ACTION = r"(?:refund(?:ed)?|credit(?:ed)?|fix(?:ed)?|resolv(?:ed|e)|escalat(?:ed|e)|sent|send|process(?:ed)?|approv(?:ed|e)|updat(?:ed|e)|cancel(?:l)?(?:ed)?|contact(?:ed)?|submitt?ed|investigat(?:ed|e)|issu(?:ed|e)|creat(?:ed|e)|check(?:ed)?|review(?:ed)?)"
_PERFORMED = re.compile(
    rf"\b(?:we|i)(?:'ve|\s+(?:have|already|successfully))*\s+{_ACTION}\b|"
    rf"\b(?:has|have|was|were|is)\s+(?:been\s+)?(?:(?:already|successfully|now)\s+)?{_ACTION}\b|"
    rf"\b(?:will|shall|should)\s+(?:be\s+)?{_ACTION}\b|"
    rf"\b(?:we|i)'ll\s+(?:have\s+)?(?:it\s+)?{_ACTION}\b",
    re.IGNORECASE,
)
_TIME_PROMISE = re.compile(
    r"\b(?:within|in)\s+(?:\d+|one|two|three|four|a|an)\s+(?:business\s+)?(?:minutes?|hours?|days?|weeks?)\b|"
    r"\b(?:guarantee(?:d)?|promise(?:d)?)\b", re.IGNORECASE,
)
_FIRST_PERSON_COMMITMENT = re.compile(
    r"\b(?:we|i|our\s+team)(?:'ll|\s+(?:will|shall)|\s+(?:are|am|is)\s+going\s+to)\b",
    re.IGNORECASE,
)


class GeneratedDetails(BaseModel):
    """Required nullable product field; no API category/sentiment overrides allowed."""

    model_config = ConfigDict(extra="forbid", strict=True, hide_input_in_errors=True)

    priority: Priority
    product_feature: str | None = Field(..., min_length=1, max_length=160)
    suggested_reply: str = Field(min_length=1, max_length=600)

    @field_validator("product_feature", "suggested_reply")
    @classmethod
    def meaningful_string(cls, value):
        if value is None:
            return None
        value = value.strip()
        if not value:
            raise ValueError("Generated text must be nonblank.")
        return value

    @field_validator("suggested_reply")
    @classmethod
    def short_draft_without_actions(cls, value):
        if "\n" in value or "\r" in value or len(re.findall(r"[.!?]+(?=\s|$)", value)) > 2:
            raise ValueError("The reply draft must be one or two short sentences.")
        normalized = value.replace("’", "'")
        if _PERFORMED.search(normalized) or _TIME_PROMISE.search(normalized) or _FIRST_PERSON_COMMITMENT.search(normalized):
            raise ValueError("The draft must not claim actions or promise a resolution/time.")
        return value

    @model_validator(mode="after")
    def grounded_product(self, info: ValidationInfo):
        message = (info.context or {}).get("message")
        if message is not None and self.product_feature is not None:
            if _normalized(self.product_feature) not in _normalized(message):
                raise ValueError("Product/feature must be an exact phrase from the customer message, or null.")
        return self
